// Arkon Customer Status API - request parsing.
// One parameter is required: the customer's reference, which is the plant's
// incident id. Every other parameter is ignored, so a caller cannot reach an
// internal filter (priority, module, assignee) through this endpoint.
const params = $input.first().json.query ?? {};
const errors = [];

const raw = (key) => {
  const value = params[key];
  if (value === undefined || value === null) return null;
  const text = String(Array.isArray(value) ? value[0] : value).trim();
  return text === "" ? null : text;
};

// reference: accepts ARK-INC-00348, ark-inc-348, or a bare number, and is
// normalised to the padded form the store holds.
let reference = raw("reference");
if (reference === null) {
  errors.push("reference is required, for example ARK-INC-00348");
} else {
  const digits = reference.replace(/[^0-9]/g, "");
  if (!/^(ARK-INC-)?[0-9]+$/i.test(reference) || digits === "") {
    errors.push("reference must look like ARK-INC-00348");
    reference = null;
  } else {
    reference = "ARK-INC-" + digits.padStart(5, "0");
  }
}

// Test affordance only, the same one the incident status API carries: lets the
// agent's failure path be demonstrated on demand without unpublishing the
// workflow. A production deployment removes it or puts it behind an operator role.
const simulateFailure = ["1", "true", "yes"].includes((raw("simulate_failure") ?? "").toLowerCase());

return [
  {
    json: {
      valid: errors.length === 0,
      errors,
      simulate_failure: simulateFailure,
      reference,
    },
  },
];

// Arkon Customer Status API - answer one reference for a customer.
// The row is the store sync's projection of the incident line with its
// transition log folded on (charter 7.2 and 7.5). What leaves this node is the
// customer projection and nothing else: nothing about the people working the
// notice, what the models saw, how urgent the plant rates it, or any other
// notice. The vocabulary and the commitment windows come from
// customer_projection.py, shared with the desk's customer documents.
const CUSTOMER_STAGES = {"new": {"customer_status": "Received", "stage": 1, "stage_name": "Received and logged", "next_step": "Acknowledgement by the Arkon quality team"}, "acknowledged": {"customer_status": "Under investigation", "stage": 2, "stage_name": "Investigation opened", "next_step": "Containment decision"}, "in_containment": {"customer_status": "Containment in place", "stage": 3, "stage_name": "Containment measures active", "next_step": "Root cause and corrective action"}, "resolved": {"customer_status": "Corrective action implemented", "stage": 4, "stage_name": "Corrective action implemented", "next_step": "Effectiveness check and closure"}, "closed": {"customer_status": "Closed", "stage": 5, "stage_name": "Closed", "next_step": null}, "false_positive": {"customer_status": "Closed, no defect confirmed", "stage": 5, "stage_name": "Closed", "next_step": null}};
const STAGE_COUNT = 5;
const COMMITMENT_HOURS = {"new": {"P1": 0.25, "P2": 1.0}, "acknowledged": 24.0, "in_containment": 240.0, "resolved": 120.0};
const DEFAULT_ACK_HOURS = 24.0;
const TERMINAL_STATUSES = ["closed", "false_positive"];
const arkonCustomerParseJson = (text, fallback) => {
  if (text === null || text === undefined || text === "") return fallback;
  try {
    return JSON.parse(text);
  } catch (error) {
    return fallback;
  }
};

// Hours Arkon has committed to for the next step of a notice in this status.
// The acknowledgement window is the charter's per priority; a priority without
// one gets the desk's default; a status without a next step gets null.
function arkonCommitmentHours(status, priority) {
  const window = COMMITMENT_HOURS[status];
  if (window === undefined) return null;
  if (typeof window === "number") return window;
  const byPriority = window[String(priority ?? "").toUpperCase()];
  return byPriority === undefined ? DEFAULT_ACK_HOURS : byPriority;
}

// One incident row of the store, seen by the customer who holds its reference.
// The current stage was entered at the last recorded transition, or at intake
// when there is none, and the commitment date counts from that moment, so a
// containment that was reopened counts from the reopening.
function arkonCustomerProjection(row, now) {
  const status = String(row.status ?? "new").toLowerCase();
  const stage = CUSTOMER_STAGES[status] ?? CUSTOMER_STAGES["new"];
  const history = arkonCustomerParseJson(row.history_json, []);
  const last = history.length ? history[history.length - 1] : null;
  const enteredAt = last && last.recorded_at ? last.recorded_at : (row.created_at ?? null);
  const entered = Date.parse(enteredAt ?? "");

  let nextStep = null;
  if (stage.next_step) {
    const hours = arkonCommitmentHours(status, row.priority);
    const due = Number.isNaN(entered) || hours === null ? null : new Date(entered + hours * 3600000);
    nextStep = {
      name: stage.next_step,
      due_at: due ? due.toISOString() : null,
      overdue: due ? now.getTime() > due.getTime() : false,
    };
  }

  const terminal = TERMINAL_STATUSES.includes(status);
  return {
    reference: row.incident_id,
    type: "quality_notice",
    received_at: row.created_at ?? null,
    customer_status: stage.customer_status,
    stage: { number: stage.stage, of: STAGE_COUNT, name: stage.stage_name },
    next_step: nextStep,
    last_update_at: enteredAt,
    closed_at: terminal ? (row.closed_at ?? enteredAt) : null,
  };
}

const request = $("Parse Reference").first().json;
const now = new Date();

const isRow = (json) => json && typeof json === "object" && typeof json.incident_id === "string";
const rows = $("Get Reference")
  .all()
  .map((item) => item.json)
  .filter(isRow)
  .filter((row) => row.incident_id === request.reference);

if (!rows.length) {
  return [
    {
      json: {
        status: "no_match",
        message: "No quality notice or complaint with reference " + request.reference + " is on record.",
        as_of: now.toISOString(),
        reference: request.reference,
        notice: null,
      },
    },
  ];
}

return [
  {
    json: {
      status: "ok",
      message: "Reference " + request.reference + " found.",
      as_of: now.toISOString(),
      reference: request.reference,
      notice: arkonCustomerProjection(rows[0], now),
    },
  },
];
